//! 🧪️ The original native wrapper publishes one independently admitted named root under its original ledger.
#[path="../../../../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::{DslValue,Number,NativeDecodeControl,NamedPersistentRoot,native_decoding::{NativeDecodeConstructionRecipient,owned::{NativeReceivingOriginal}}};
#[derive(semio_framework_value_derive::RetireOwned,semio_framework_value_derive::NativeReceive)]#[value(crate="crate",native_owned="::semio_framework_value_native_owned")]struct ReceivedRow{key:SealedShared<String>,payload:i64}
impl crate::NamedRecordKey for ReceivedRow{fn named_record_key(&self)->&str{self.key.as_str()}}
impl Clone for ReceivedRow{fn clone(&self)->Self{panic!("original named receiving cannot clone typed rows")}}

struct ConstructionTurn{original:RetainedCloneGrant,accepted:bool}
impl NativeDecodeConstructionRecipient for ConstructionTurn{
 fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"named receiver already holds its original explicit grant"))}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(!self.accepted);assert_eq!(g.maximum_items,self.original.maximum_items);assert!(g.maximum_copy_bytes<=self.original.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.original.maximum_capacity_bytes&&g.maximum_release_bytes<=self.original.maximum_release_bytes&&g.maximum_depth<=self.original.maximum_depth);assert!(p.fits(g));self.accepted=true;Ok(())}
}
fn receive<R>(control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,f:impl FnOnce(&mut NativeDecodeControl<'_>)->crate::RetainedWorkOutcome<R,crate::OriginalReceivingPrimary>)->crate::RetainedWorkOutcome<R,crate::OriginalReceivingPrimary>{let mut recipient=ConstructionTurn{original:g,accepted:false};let mut work=0;let result=control.with_construction_recipient(&mut recipient,|control|{let turn=f(control);work=turn.work;turn.result});crate::RetainedWorkOutcome{result,work}}

fn fund(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:257,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close_fund(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");RetainedCloneGrant{maximum_copy_bytes:4096,..fund(d)}}
fn funding_vectors(f:&serde_json::Value){for row in f["copyFunding"].as_array().unwrap(){let d=RetirementDemand{copy_bytes:row["quotedCopy"].as_u64().unwrap()as usize,capacity_bytes:7,release_bytes:11,depth:3};let g=if row["purpose"]=="forward"{fund(d)}else{close_fund(d)};assert_eq!(g.maximum_copy_bytes,row["maximumCopy"].as_u64().unwrap()as usize);assert_eq!((g.maximum_capacity_bytes,g.maximum_release_bytes,g.maximum_depth),(d.capacity_bytes,d.release_bytes,d.depth));}}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn close_value<T:RetireOwned>(value:T,total:&mut(usize,usize)){let(mut close,h)=heap(||ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap());total.0+=h.0;total.1+=h.1;let mut close_work=close_work_policy::Work::new();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=close_fund(d);let(s,h)=heap(||close.step(g).unwrap());account(s.progress(),g,h,total);close_work.observe(s.progress()==Default::default()&&!close.terminal_is_empty()&&close.next_demand(4096).unwrap()==d);}assert_eq!(heap(||drop(close)).1,(0,0));}
fn run_received(keys:&[String],admitted:bool,cut:Option<usize>){
 type Owner=NativeReceivingOriginal<DslValue,NamedPersistentRoot<ReceivedRow>>;
 let(mut original,mut total)=heap(||Some(source(DslValue::Array(keys.iter().enumerate().map(|(rank,key)|DslValue::Object(vec![("key".into(),DslValue::String(key.clone())),("payload".into(),DslValue::Number(Number::Int(rank as i64)))])).collect()))));
 let pointer=std::ptr::from_ref(original.as_ref().unwrap().borrow().get());let expected=serde_json::Value::from(original.as_ref().unwrap().borrow().get());let mut owner=Owner::new(original.take().unwrap());assert!(original.is_none());assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);
 let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut prepared=0;assert_eq!(control.owned_bytes(),prepared);let mut turns=0;let mut refused=false;
 while !owner.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demands(4096).unwrap();let g=fund(d);for denied in denies(d){let(s,h)=heap(||receive(&mut control,denied,|control|owner.advance(control,4096,denied)).result.unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());assert_eq!(owner.demands(4096).unwrap(),d);}let(turn,h)=heap(||receive(&mut control,g,|control|owner.advance(control,4096,g)));let result=turn.result;let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.progress);account(p,g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(owner.borrow_input().unwrap().get()),pointer);assert_eq!(serde_json::Value::from(owner.borrow_input().unwrap().get()),expected);turns+=1;assert!(turns<1000000);if let Err(e)=result{assert_eq!(e.primary.unwrap().kind,ValueRefusalKind::InvalidValue);refused=true;break;}}
 let mut output=None;if cut.is_none(){assert_eq!(owner.output_ready(),admitted);assert_eq!(refused,!admitted);if admitted{let g=fund(owner.take_demand().unwrap());let((root,p),h)=heap(||owner.take(g).result.unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),keys.len());let ranked=root.ranked().unwrap();for(rank,key)in keys.iter().enumerate(){let row=ranked.original.get().get(rank).unwrap();assert_eq!(row.key.as_str(),key);assert_eq!(row.payload,rank as i64);}output=Some(root);}}
 owner.begin_close();let mut close_work=close_work_policy::Work::new();while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");for denied in denies(d){let(s,h)=heap(||owner.close_step(denied).result.unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let g=close_fund(d);control.charge(d.capacity_bytes).unwrap();let(s,h)=heap(||owner.close_step(g).result.unwrap());account(s.progress(),g,h,&mut total);prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);close_work.observe(s.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.close_demands(4096).unwrap()==d);}assert_eq!(heap(||drop(owner)).1,(0,0));
 if let Some(root)=output{let d=root.project_index_demand().unwrap();let mut projected=None;for _ in 0..2{let(turn,h)=heap(||root.project_index(&mut projected,fund(d)));let p=turn.result.unwrap().progress();account(p,fund(d),h,&mut total);}let mut alias=projected.unwrap();assert!(alias.ready());let ranked=root.ranked().unwrap();let original_key=ranked.key;let d=RetainedOwnedProjection::<PersistentList<ReceivedRow>>::constructor_demand();for denied in denies(d){let(result,h)=heap(||root.project_rows(denied));assert!(result.result.is_err());assert_eq!(h,(0,0));}let((mut reader,p),h)=heap(||root.project_rows(fund(d)).result.unwrap());assert!(reader.matches_source(ranked.original));account(p,fund(d),h,&mut total);close_value(root,&mut total);let live=PersistentRankedKeys{original:reader.borrow().unwrap(),key:original_key};for(rank,key)in keys.iter().enumerate(){assert_eq!(lookup(&live,&alias,key).0,Some(rank));}let(b,r)=close_index(&mut alias);total.0+=b;total.1+=r;let mut close_work=close_work_policy::Work::new();while !reader.terminal_is_empty(){let d=reader.close_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=fund(d);let(s,h)=heap(||reader.close_step(g).result.unwrap());account(s.progress(),g,h,&mut total);close_work.observe(s.progress()==Default::default()&&!reader.terminal_is_empty()&&reader.close_demand(4096).unwrap()==d);}assert_eq!(heap(||drop(reader)).1,(0,0));}
 assert_eq!(total.0,total.1,"original input, typed pages, admission directory and independent source must settle on the same physical ledger");
}
#[test]fn original_named_receiving_publishes_independent_roots_and_closes_every_paid_cut(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/🌳️root/🛬️receive/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();funding_vectors(&f);for row in f["cases"].as_array().unwrap(){let keys=row["keys"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>();for cut in f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run_received(&keys,row["admitted"].as_bool().unwrap(),cut);}}}
#[test]fn original_named_receiving_checks_full_utf8_under_original_decoder_quantum(){let f:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/🌳️root/🛬️receive/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();funding_vectors(&f);let prefix=f["prefix"].as_str().unwrap().repeat(f["repeat"].as_u64().unwrap()as usize);assert_eq!(prefix.len(),65538);for cut in f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run_received(&[prefix.clone(),format!("{prefix}x")],true,cut);}}
